1	// Package archive extracts gzipped tar archives from Crow into an
2	// in-memory file map. Diff and TUI layers consume the resulting Module
3	// type and never touch the network themselves.
4	package archive
5	
6	import (
7		"archive/tar"
8		"bytes"
9		"compress/gzip"
10		"errors"
11		"fmt"
12		"io"
13	)
14	
15	// Module is the in-memory representation of an extracted module tarball.
16	// Keys are forward-slash relative paths. Symlinks are not stored.
17	type Module struct {
18		Files map[string][]byte
19	}
20	
21	var (
22		ErrTooLarge   = errors.New("archive exceeds size cap")
23		ErrUnsafePath = errors.New("archive contains unsafe path")
24	)
25	
26	// Extract decompresses and untars tarball into a Module. If the
27	// cumulative uncompressed size exceeds maxBytes, Extract returns
28	// ErrTooLarge. Paths containing ".." or absolute roots are rejected with
29	// ErrUnsafePath. Symlinks are dropped silently (they are not useful
30	// inputs to a textual or semantic diff).
31	func Extract(tarball []byte, maxBytes int64) (Module, error) {
32		gz, err := gzip.NewReader(bytes.NewReader(tarball))
33		if err != nil {
34			return Module{}, fmt.Errorf("gzip: %w", err)
35		}
36		defer gz.Close()
37	
38		tr := tar.NewReader(gz)
39		files := make(map[string][]byte)
40		var total int64
41		for {
42			hdr, err := tr.Next()
43			if errors.Is(err, io.EOF) {
44				break
45			}
46			if err != nil {
47				return Module{}, fmt.Errorf("tar: %w", err)
48			}
49			switch hdr.Typeflag {
50			case tar.TypeReg, tar.TypeRegA: //nolint:staticcheck
51				if err := safePath(hdr.Name); err != nil {
52					return Module{}, err
53				}
54				total += hdr.Size
55				if total > maxBytes {
56					return Module{}, ErrTooLarge
57				}
58				body := make([]byte, hdr.Size)
59				if _, err := io.ReadFull(tr, body); err != nil {
60					return Module{}, fmt.Errorf("reading %s: %w", hdr.Name, err)
61				}
62				files[hdr.Name] = body
63			default:
64				// Directories, symlinks, etc. ignored.
65			}
66		}
67		return Module{Files: files}, nil
68	}
69	
70	func safePath(name string) error {
71		if name == "" {
72			return fmt.Errorf("%w: empty name", ErrUnsafePath)
73		}
74		if name[0] == '/' {
75			return fmt.Errorf("%w: absolute path %q", ErrUnsafePath, name)
76		}
77		// Reject any segment that is "..", or any path containing "..".
78		for i := 0; i < len(name); i++ {
79			if name[i] == '\\' {
80				return fmt.Errorf("%w: backslash in path %q", ErrUnsafePath, name)
81			}
82		}
83		if containsDotDot(name) {
84			return fmt.Errorf("%w: path traversal in %q", ErrUnsafePath, name)
85		}
86		return nil
87	}
88	
89	func containsDotDot(p string) bool {
90		for i := 0; i < len(p); i++ {
91			if p[i] != '.' {
92				continue
93			}
94			// Check for ".." preceded by start-or-slash, followed by slash-or-end.
95			if i+1 < len(p) && p[i+1] == '.' {
96				startOK := i == 0 || p[i-1] == '/'
97				endOK := i+2 == len(p) || p[i+2] == '/'
98				if startOK && endOK {
99					return true
100				}
101			}
102		}
103		return false
104	}
